<template><Layout><div class="breadcrumb"><Link :href="route('dashboard')">Overview</Link><span>›</span>Payments</div><div class="page-header list-header"><div><div class="eyebrow">CHECKOUT SETTINGS</div><h1>Payment methods</h1><p>Manage the options sellers and customers use for transactions.</p></div><Link :href="route('payments.create')" class="primary-button">＋ New payment method</Link></div><section class="payment-summary"><div><span>{{ payments.length }}</span><p><strong>Total methods</strong><small>Configured options</small></p></div><div><span>{{ activeCount }}</span><p><strong>Active methods</strong><small>Available for use</small></p></div><div><span>{{ usageCount }}</span><p><strong>Listing links</strong><small>Across all products</small></p></div></section><section class="listing-panel"><div class="listing-toolbar"><div class="list-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input v-model="query" placeholder="Search payment methods…"/></div><span>{{ filtered.length }} results</span></div><div v-if="filtered.length" class="payment-list"><div class="payment-row payment-head"><span>Payment method</span><span>Status</span><span>Listings</span><span>Orders</span><span></span></div><Link v-for="item in filtered" :key="item.id" :href="route('payments.edit',item.id)" class="payment-row"><div class="payment-identity"><i>{{ initials(item.name) }}</i><div><strong>{{ item.name }}</strong><small>Added {{ formatDate(item.created_at) }}</small></div></div><span><b class="status-dot" :class="{off:!item.is_active}"></b>{{ item.is_active?'Active':'Inactive' }}</span><span>{{ item.product_payments_count }}</span><span>{{ item.orders_count }}</span><b>›</b></Link></div><div v-else class="empty-state"><div>◇</div><strong>{{ query?'No matching methods':'No payment methods yet' }}</strong><p>{{ query?'Try another search term.':'Add the first payment option for your marketplace.' }}</p><Link v-if="!query" :href="route('payments.create')" class="primary-button">Create payment method</Link></div></section></Layout></template>
<script setup>import{ref,computed,onMounted}from'vue';import{usePage}from'@inertiajs/vue3';import{useToast}from'vue-toastification';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({payments:{type:Array,default:()=>[]}}),query=ref('');const filtered=computed(()=>props.payments.filter(p=>p.name.toLowerCase().includes(query.value.toLowerCase()))),activeCount=computed(()=>props.payments.filter(p=>p.is_active).length),usageCount=computed(()=>props.payments.reduce((s,p)=>s+p.product_payments_count,0));const initials=n=>n.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase(),formatDate=d=>new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(d));const page=usePage(),toast=useToast();onMounted(()=>{if(page.props.flash?.success)toast.success(page.props.flash.success)});</script>
